insert into public.crates (name, position, layer, plane, plain_summary, why_it_matters, deps, badge, code)
select name, position, layer, plane, plain_summary, why_it_matters, deps, badge, code from jsonb_populate_recordset(null::public.crates, $j$[{"name":"crates/forge-types","position":1,"layer":"Layer 0 · Foundation Leaf","plane":"Plane 3 · Authoritative Daemon","plain_summary":"Defines all shared identifiers, error types, and our compile-time deadlock prevention tokens.","why_it_matters":"In competitor audits (like jcode#1828), threads deadlocked when acquiring locks in opposite orders. forge-types uses zero-sized Rust phantom tokens (L0Root -> L1EnvConfig -> L2SessionController -> L3SurfaceState) so out-of-order lock code refuses to compile.","deps":"None (Zero-dependency leaf crate)","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-types/src/lock_order.rs\n// Compile-Time Lock Hierarchy: prevents ABBA deadlocks (jcode#1828) at compile time.\npub enum L0Root {}\npub enum L1EnvConfig {}\npub enum L2SessionController {}\npub enum L3SurfaceState {}\n\npub struct OrderedMutex<Level, T> {\n    inner: parking_lot::Mutex<T>,\n    _level: std::marker::PhantomData<Level>,\n}\n// Also validates rkyv = \"0.8\" caches strictly via rkyv::access::<Archived<T>, rancor::Error>"},{"name":"crates/forge-hw","position":2,"layer":"Layer 1 · Core Infrastructure","plane":"Plane 3 · Authoritative Daemon","plain_summary":"Detects your exact CPU, RAM, GPU VRAM, and NPU limits to size local models safely.","why_it_matters":"Earlier audits mistakenly sized Mixture-of-Experts (MoE) models by active parameters, which causes instant OOM crashes. forge-hw vendors llmfit-core v1.1.10 and calculates resident capacity across split GPU VRAM + Host DDR5 RAM (-ngl), using active parameters strictly for tok/s speed.","deps":"forge-types","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-hw/src/moe_fit.rs — Split GPU VRAM + Host DDR5 RAM MoE Admission (Patch F.4)\n// 1. Resident Capacity (100% of total parameters P_total must reside in VRAM + RAM):\n//    VRAM_req = (P_shared_attn + P_experts_vram) * b_quant + KV_vram + B_compute <= VRAM_avail\n//    RAM_req  = P_experts_ram * b_quant + KV_ram + RSS_daemon_shell <= 0.85 * Free_RAM\n// 2. Generation Throughput (governed by active parameters per token P_active):\n//    tok/s_eff = 1.0 / ((P_active_vram * b_quant / BW_vram) + (P_active_ram * b_quant / min(BW_ddr, BW_pcie)))"},{"name":"crates/forge-db","position":3,"layer":"Layer 1 · Core Infrastructure","plane":"Plane 3 · Authoritative Daemon","plain_summary":"Manages our single authoritative SQLite WAL database, FTS5 search, and Zero-Token Pre-Wake Gate.","why_it_matters":"Splitting relational tables across two SQLite files breaks foreign keys and atomic commits with vector_outbox. forge-db keeps all relational tables in authoritative_audit.db, dynamically toggling PRAGMA synchronous = FULL on approvals/checkouts and NORMAL on streaming chunks.","deps":"forge-types","badge":"VERIFIED_PRIMARY_SOURCE","code":"-- crates/forge-db/migrations/0001_authoritative_audit.sql\nPRAGMA journal_mode = WAL;\nPRAGMA foreign_keys = ON;\n-- Zero-Token SQLite Pre-Wake Gate (<0.1ms in Rust, 0 LLM tokens burned on empty inbox, fixing paperclip#3401):\nSELECT EXISTS(\n  SELECT 1 FROM tasks\n  WHERE assignee_agent_id = ?1 AND status IN ('PENDING', 'IN_REVIEW')\n) AS has_actionable_work;"},{"name":"crates/forge-sandbox","position":4,"layer":"Layer 1 · Core Infrastructure","plane":"Plane 4 · Preemptible OS Worker Pool","plain_summary":"Enforces kernel-level sandboxing and <15 ms atomic subtree termination across Linux, Windows, and macOS.","why_it_matters":"Rust's catch_unwind and tokio::time::timeout cannot stop a hung C++ FFI call or a forked grandchild that called setsid(). forge-sandbox uses Linux cgroup.kill + /usr/lib/geminiforge/gf-bwrap-helper, Windows JobObjects + AppContainer SIDs, and macOS Seatbelt + kqueue.","deps":"forge-types, forge-hw","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-sandbox/src/lib.rs — 3-OS Atomic Subtree Supervisor\n#[async_trait::async_trait]\npub trait SubtreeSupervisor: Send + Sync {\n    async fn spawn_isolated(&self, cmd: &[String], policy: &SandboxPolicy) -> Result<WorkerHandle>;\n    /// Atomically kills worker AND 100% of forked grandchildren across setsid() in < 15 ms\n    /// via Linux cgroup.kill, Windows TerminateJobObject, or macOS killpg + kqueue EVFILT_PROC.\n    async fn kill_subtree_atomic(&self, handle: &WorkerHandle) -> Result<()>;\n}"},{"name":"crates/forge-policy","position":5,"layer":"Layer 2 · Security & VCS","plane":"Plane 3 · Authoritative Daemon","plain_summary":"Evaluates temporal security rules, pre-trust repository scans, and wire-level credential injection.","why_it_matters":"Stateless tool rules cannot stop an agent that reads a private .env file at step 1 and exfiltrates it over HTTP at step 2. forge-policy tracks session event history in SQLite (read_sensitive -> forbid(egress)) and injects API keys on the host wire so sandboxes hold only stand-in tokens.","deps":"forge-types, forge-db, forge-sandbox","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-policy/src/temporal.rs — Clean-Room Temporal Event-History Evaluator\n// • Per-agent principal scoping (agent_id) + atomic IN_FLIGHT_RESERVED budget counters\n// • Temporal rule: if session history contains 'fs:read_sensitive', deny 'net:egress' & 'mcp:external'\n// • Pre-trust repo gate: affaan-m/agentshield 268 rules with runtimeConfidence weighting (1.0x active vs 0.25x template)"},{"name":"crates/forge-vcs","position":6,"layer":"Layer 2 · Security & VCS","plane":"Plane 3 & Plane 4","plain_summary":"Provides lock-free Jujutsu (jj-lib v0.46.0) multi-agent workspaces and <2 ms in-memory patch application.","why_it_matters":"When 20 agents run git commit concurrently, .git/index.lock contention and working-tree conflicts corrupt the repo. jj-lib uses a lock-free StackedTable operation log, algebraic conflict trees, <50 ms jj op undo, and in-memory imara-diff (fixing Windows codex#15003).","deps":"forge-types, forge-db","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-vcs/src/lib.rs — Embedded jj-lib v0.46.0 + Optimistic File Leases\n// • Zero .git/index.lock contention across 20 concurrent coding agents\n// • DashMap<CanonicalPath, FileLease> verifies blake3 pre-write hashes so unsaved editor buffers are never clobbered"},{"name":"crates/forge-search","position":7,"layer":"Layer 2 · Security & VCS","plane":"Plane 3 & Plane 4","plain_summary":"Maintains the incremental Tree-sitter 0.27 AST symbol graph and deduplicates .forge/AGENTS.md guidelines.","why_it_matters":"Combines 200k-file blake3 Merkle indexing, petgraph PageRank RepoMaps, 4-mode agentgrep queries (grep, find, outline, trace), and JetBrains Junie's hierarchical guidelines discovery (.forge/AGENTS.md -> .junie/AGENTS.md -> AGENTS.md -> ~/.forge/AGENTS.md).","deps":"forge-types, forge-db","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-search/src/guidelines.rs — Junie-Compatible Hierarchical Guidelines Loader\n// 1. Project-level .forge/AGENTS.md & .junie/AGENTS.md (Highest Priority)\n// 2. Repo root AGENTS.md / CLAUDE.md / GEMINI.md + .forge/playbook.md\n// 3. Global ~/.forge/AGENTS.md (Deduplicated by blake3 paragraph hash)"},{"name":"crates/forge-pty","position":8,"layer":"Layer 2 · Security & VCS","plane":"Plane 3 · Authoritative Daemon","plain_summary":"Supervises terminal PTY rings, parses OSC 7501 program status sequences, and routes gf-tmux-shim.","why_it_matters":"Instead of fragile regex prompt scraping to guess if a CLI tool is waiting for permission, forge-pty parses Mitchell Hashimoto's OSC 7501 (rev 0.2) escape sequence (\\e]7501;state=blocked:kind=permission\\e\\\\) and surfaces a 1-click card in the Unified Approval Inbox in <5 ms.","deps":"forge-types, forge-sandbox","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-pty/src/osc7501.rs — OSC 7501 Program Status VT Parser (Revision 0.2)\n// • Replies to OSC 7501 ; ? ST capability probes from Bubble Tea v2.1.0 / Charm Crush v0.98.0\n// • Caps status records at 256 per pane (LRU) and supersedes OSC 9;4 progress bars until reset"},{"name":"crates/forge-protocols","position":9,"layer":"Layer 3 · Protocols & Extensions","plane":"Plane 3 · 5-Protocol Hub","plain_summary":"Implements MCP 2026-07-28, ACP v3.2.0 Conductor, A2A v0.14.1+, AG-UI 1.0, A2UI v0.9, and Two-Speed routing.","why_it_matters":"Stuffing 200 MCP tool schemas into a prompt burns 40,000 tokens per turn. forge-protocols exposes the 4-Meta-Tool Capability Gateway (~480 tokens baseline), wraps rmcp v3.5.1 in a 16 MiB BoundedJsonRpcLineReader (fixing rmcp#1030), and chains ACP v3.2.0 proxies.","deps":"forge-types, forge-db, forge-sandbox, forge-policy, forge-vcs","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-protocols/src/lib.rs — 5-Protocol Interoperability Spine\n// • MCP 2026-07-28 (rmcp v3.5.1 + 16 MiB line cap + SEP-2567 server/discover + 300s idle SIGTERM in McpMux)\n// • ACP v3.2.0 Conductor (ForgePolicyProxy -> ForgeFileLeaseProxy -> ForgeMcpBridgeProxy + 5-session recycling)\n// • A2A (a2a-rust >= 0.14.1 fixing GHSA-hr9h-6jvf-wvg6 + 11 A2ABreak guards) + AG-UI 1.0 + A2UI v0.9"},{"name":"crates/forge-mods","position":10,"layer":"Layer 3 · Protocols & Extensions","plane":"Plane 2 · Sandboxed VM","plain_summary":"Executes .gmod.ts extensions and MCP Code Mode scripts inside a <4 MB / 64 MB Wasmtime QuickJS guest.","why_it_matters":"Running 10 UI Mods in 64 MB V8 Workers consumes 640 MB of RAM. forge-mods compiles .gmod.ts via swc in <15 ms into a wasmtime rquickjs (wasm32-wasip1) sandbox (<4 MB heap, 50 ms epoch preemption) that emits declarative A2UI v0.9 JSON to React 19.","deps":"forge-types, forge-db, forge-policy, forge-protocols","badge":"DESIGN_HYPOTHESIS — REQUIRES_SPIKE","code":"// crates/forge-mods/src/lib.rs — Sandboxed QuickJS-WASM Guest & MCP Code Mode (SEP-2106)\n// • .gmod.ts Mods: < 4 MiB linear memory cap, 50 ms epoch interruption, emits A2UI v0.9 JSON deltas\n// • MCP Code Mode: compiles SEP-2106 schemas into .d.ts and runs 50-step tool loops in 1 turn (90–94% token savings)"},{"name":"crates/forge-cu","position":11,"layer":"Layer 3 · Protocols & Extensions","plane":"Plane 5 · Computer-Use Engine","plain_summary":"Routes desktop and browser actions across Environments A/B/C and Mechanisms 0/1/2/3.","why_it_matters":"Separates WHERE an app runs (Headless Env A, Isolated PiP Virtual Display Env B, or Host Desktop Env C) from HOW it is driven (Mech 0 CLI-Anything <15 ms, Mech 1 Playwright/Lightpanda CDP, Mech 2 Drained AT-SPI2 / HWND UIA, Mech 3 UI-TARS Vision + VPI-Bench Guard).","deps":"forge-types, forge-hw, forge-sandbox, forge-policy, forge-protocols","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-cu/src/router.rs — Orthogonal Computer-Use Action Router\n// • Fixes trycua/cua#4894 (stateless/drained zbus AT-SPI2 so Qt6 apps never hang)\n// • Fixes trycua/cua#4963 (ScreenReaderEnabled=false so GNOME Orca never launches)\n// • Fixes trycua/cua#4906 (EnumWindows + ElementFromHandle <2ms on Windows 10/11)"},{"name":"crates/forge-swarm","position":12,"layer":"Layer 4 · Orchestration","plane":"Plane 3 & Plane 4","plain_summary":"Coordinates 20-agent swarms, Paperclip org-charts, Confidence Stepping, and ForgeLab simulations.","why_it_matters":"Unites Microsoft UFO3's TaskConstellation DAG, Paperclip's Goal-Ancestry breadcrumbs and Atomic 409 Checkout, jcode's Confidence Stepping, Typed Evidence Receipts (preventing MiroFish#529 fake quotes), and DeepMind Concordia's Game Master causal referee.","deps":"forge-types, forge-db, forge-vcs, forge-search, forge-protocols, forge-cu","badge":"VERIFIED_PRIMARY_SOURCE","code":"// crates/forge-swarm/src/lib.rs — Org-Swarm & Grounded Simulation Coordinator\n// • Rejects >=15% confidence jumps to 100% without a new passing verification ToolCallId\n// • Requires TypedEvidenceReceipt (file_path, jj_change_id, test_exit_code, blake3_artifact_hash)"},{"name":"bins/geminiforge-daemon","position":13,"layer":"Layer 5 · Authoritative Binary","plane":"Plane 3 · Authoritative Daemon","plain_summary":"The single authoritative control daemon, geminiforge-lite browser bridge, and Zero-Token RRule cron runner.","why_it_matters":"Acquires an exclusive kernel advisory lock (flock / LockFileEx) before unlinking stale sockets or calling iceoryx2 cleanup_dead_nodes(), and transitions interrupted non-idempotent tools to INTERRUPTED_UNCERTAIN for human reconciliation.","deps":"All library crates","badge":"VERIFIED_PRIMARY_SOURCE","code":"// bins/geminiforge-daemon/src/main.rs\n// Baseline RSS: 28–65 MB. Serves AG-UI 1.0 + A2UI v0.9 over 0600 UDS (SO_PEERCRED) or Owner-SID Named Pipe."},{"name":"bins/forge-worker, gf-tmux-shim & gf-emergency-hud","position":14,"layer":"Layer 5 · Worker & HUD Binaries","plane":"Plane 1 & Plane 4","plain_summary":"Pre-warmed multi-call sandbox worker, tmux CLI pane translator, and <2 ms iced.rs Super+Escape HUD.","why_it_matters":"forge-worker isolates risky parsers (mmdr, search, a11y, duckdb, unpack) inside cgroup leaves, while gf-emergency-hud uses pure-Rust iced.rs (wgpu with automatic tiny-skia CPU fallback) to render the Super+Escape kill switch in <2 ms.","deps":"forge-types, forge-sandbox, forge-search, forge-cu, iced","badge":"VERIFIED_PRIMARY_SOURCE","code":"// bins/gf-emergency-hud/src/main.rs — Scoped iced.rs Native Overlay (CONFIRM-08)\n// Maps in < 2 ms on Super+Escape using renderer/src/fallback.rs (wgpu -> tiny-skia CPU software rasterizer)."}]$j$::jsonb);
